command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="eccc723ce730b49be79626cf2e5794d1e2a9fabc"
$newBranch="work/f5-f6-main-reapply-20261006"
$newSha="1f53be6716adf67cccbbda74ed3f2d86240f3e3e"
$oldBranch="work/f5-f6-semantics-20261006"
$oldSha="21fcaa28aa11dc72cfae42d9cd32010298adfff4"
Set-Location -LiteralPath $repo
& git fetch origin main $newBranch $oldBranch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "F5/F6 cleanup fetch failed"}
$mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
if($mainSha -ne $main){throw "main moved before F5/F6 cleanup: $mainSha"}
$newRef="refs/remotes/origin/"+$newBranch
$oldRef="refs/remotes/origin/"+$oldBranch
if((& git rev-parse $newRef).Trim() -ne $newSha){throw "new F5/F6 branch moved before cleanup"}
if((& git rev-parse $oldRef).Trim() -ne $oldSha){throw "old F5/F6 branch moved before cleanup"}
& git merge-base --is-ancestor $newSha refs/remotes/origin/main
if($LASTEXITCODE -ne 0){throw "integrated F5/F6 branch tip is not preserved in main ancestry"}
& git push origin --delete $newBranch $oldBranch
if($LASTEXITCODE -ne 0){throw "failed to delete F5/F6 branches"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
if(& git show-ref --verify --quiet $newRef){throw "new F5/F6 remote branch still exists"}
if(& git show-ref --verify --quiet $oldRef){throw "old F5/F6 remote branch still exists"}
Write-Host "F5_F6_MERGED_BRANCH_CLEANUP=PASS"
